//! `migration::migrate` (lot 6.1) against the scenarios that the .NET `InstanceMigration.Migrate`
//! played (`rust/tests/golden/migration.json`, regenerated by `rust/tools/migrate-oracle`), each
//! on a fresh copy of the format 1 fixture of `MigrationTests` (copied, never modified). The
//! steps (raw SQL, file writes and removals, migrations, interruptions, the race, dumps) are
//! replayed in order. A dump runs the SQL recorded by the oracle on the database and on each
//! backup, and compares `instance.json` (line breaks of the platform as `\n`) and the
//! projections.
//!
//! The interruption points are the `StepHook` of the oracle, here the hook of
//! [`migrate_with`]: a crash is a failure of the hook at that step, never a sleep.
//!
//! A lock is held by another connection between `lock` and `unlock`; a migration or a backup
//! timed by the oracle is compared by bucket of elapsed time (`<1s`, `1-4s`, `>=4s`).

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::Instant;

use rusqlite::types::ValueRef;
use rusqlite::{Connection, OpenFlags};
use serde_json::{Value, json};
use sermofur_core::discovery::expand_short_names;
use sermofur_core::error::{Result, SermofurError};
use sermofur_core::migration::{MigrationResult, back_up, migrate, migrate_with};
use sermofur_core::{NEW_LINE, json as dotnet_json, schema};
use uuid::Uuid;

/// A folder under the temporary directory, removed on drop: every connection of a step is
/// closed before the step ends, so nothing holds a file when it goes.
struct Folder(PathBuf);

impl Drop for Folder {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/Sermofur.Tests/Fixtures/instance-v1/marker")
}

fn copy(source: &Path, target: &Path) {
    fs::create_dir_all(target).expect("folder");
    for entry in fs::read_dir(source).expect("listing") {
        let path = entry.expect("entry").path();
        let to = target.join(path.file_name().expect("name"));
        if path.is_dir() {
            copy(&path, &to);
        } else {
            fs::copy(&path, &to).expect("copy");
        }
    }
}

/// A copy of the fixture of `LegacyInstance`: the marker and the folders of its scopes.
fn legacy_instance() -> Folder {
    let temp = std::env::temp_dir();
    let base = if cfg!(windows) {
        expand_short_names(&temp)
    } else {
        fs::canonicalize(temp).expect("temp")
    };
    let root = base.join(format!("sermofur-migrate-{}", Uuid::new_v4().simple()));
    let folder = Folder(root.clone());
    fs::create_dir_all(root.join("client-a").join("project-x")).expect("scopes");
    fs::create_dir_all(root.join("client-b")).expect("scopes");
    copy(&fixture(), &root.join(".sermofur"));
    folder
}

/// `memory-v1-<yyyyMMddTHHmmssZ>-<guid32>.db` with its variable parts as the oracle wrote them.
fn normalize(text: &str) -> String {
    const PREFIX: &str = "memory-v1-";
    let mut out = String::new();
    let mut rest = text;
    while let Some(at) = rest.find(PREFIX) {
        let tail = &rest[at + PREFIX.len()..];
        let shape = tail.as_bytes();
        let matches = shape.len() >= 52
            && shape[..8].iter().all(u8::is_ascii_digit)
            && shape[8] == b'T'
            && shape[9..15].iter().all(u8::is_ascii_digit)
            && shape[15] == b'Z'
            && shape[16] == b'-'
            && shape[17..49]
                .iter()
                .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(c))
            && &shape[49..52] == b".db";
        out.push_str(&rest[..at + PREFIX.len()]);
        if matches {
            out.push_str("<stamp>-<id>.db");
            rest = &tail[52..];
        } else {
            rest = tail;
        }
    }
    out.push_str(rest);
    out
}

/// The bucket of elapsed time of the oracle.
fn bucket(start: Instant) -> &'static str {
    match start.elapsed().as_secs_f64() {
        seconds if seconds < 1.0 => "<1s",
        seconds if seconds >= 4.0 => ">=4s",
        _ => "1-4s",
    }
}

fn crash() -> SermofurError {
    SermofurError::new("crash", "simulated crash", 0)
}

/// The answer as the oracle records it.
fn answer(result: Result<MigrationResult>) -> Value {
    match result {
        Ok(result) => Value::String(normalize(
            &dotnet_json::to_string(&result)
                .expect("JSON")
                .replace(NEW_LINE, "\n"),
        )),
        Err(error) if error.code == "crash" => json!({ "crash": true }),
        Err(error) => refusal(&error),
    }
}

fn refusal(error: &SermofurError) -> Value {
    json!({
        "code": error.code,
        "message": error.message,
        "exitCode": error.exit_code,
    })
}

fn cell(value: ValueRef<'_>) -> Value {
    match value {
        ValueRef::Null => Value::Null,
        ValueRef::Integer(number) => json!(number),
        ValueRef::Text(text) => json!(String::from_utf8_lossy(text)),
        ValueRef::Blob(bytes) => {
            json!(format!(
                "blob:{}",
                bytes.iter().map(|b| format!("{b:02x}")).collect::<String>()
            ))
        }
        ValueRef::Real(real) => panic!("no real number expected, got {real}"),
    }
}

fn rows(connection: &Connection, sql: &str) -> Value {
    let mut statement = connection.prepare(sql).expect(sql);
    let count = statement.column_count();
    let mut found = Vec::new();
    let mut cursor = statement.query([]).expect(sql);
    while let Some(row) = cursor.next().expect(sql) {
        found.push(Value::Array(
            (0..count)
                .map(|i| cell(row.get_ref(i).expect("cell")))
                .collect(),
        ));
    }
    Value::Array(found)
}

/// Runs the queries recorded by the oracle on `file` and compares their rows.
fn check_database(file: &Path, expected: &Value, context: &str) {
    let connection = Connection::open_with_flags(file, OpenFlags::SQLITE_OPEN_READ_ONLY)
        .expect("database opened");
    for table in expected.as_array().expect("tables") {
        let sql = table["sql"].as_str().expect("sql");
        assert_eq!(rows(&connection, sql), table["rows"], "{context}: {sql}");
    }
}

fn check_dump(root: &Path, expected: &Value, context: &str) {
    let marker = root.join(".sermofur");
    check_database(
        &marker.join("memory.db"),
        &expected["database"],
        &format!("{context}, memory.db"),
    );
    let mut backups: Vec<PathBuf> = fs::read_dir(marker.join("backups"))
        .map(|list| list.map(|entry| entry.expect("entry").path()).collect())
        .unwrap_or_default();
    backups.sort();
    let copies = expected["backups"].as_array().expect("backups");
    assert_eq!(backups.len(), copies.len(), "{context}: backups");
    for (file, copy) in backups.iter().zip(copies) {
        let name = file.file_name().expect("name").to_string_lossy();
        assert_eq!(normalize(&name), copy["name"], "{context}: backup name");
        // A backup that failed on a locked source stays as an empty file.
        let empty = fs::metadata(file).expect("backup").len() == 0;
        assert_eq!(
            empty,
            copy["database"] == json!([]),
            "{context}, {name}: empty"
        );
        check_database(file, &copy["database"], &format!("{context}, {name}"));
    }
    let instance = fs::read_to_string(marker.join("instance.json")).expect("instance.json");
    assert_eq!(
        instance.replace(NEW_LINE, "\n"),
        expected["instance"],
        "{context}: instance.json"
    );
    let projections: BTreeMap<String, Value> = fs::read_dir(marker.join("records"))
        .expect("records")
        .map(|entry| {
            let path = entry.expect("entry").path();
            (
                path.file_name()
                    .expect("name")
                    .to_string_lossy()
                    .into_owned(),
                json!(fs::read_to_string(&path).expect("projection")),
            )
        })
        .collect();
    assert_eq!(
        json!(projections),
        expected["projections"],
        "{context}: projections"
    );
}

/// Replays `step`; `holder` is the connection of another process that holds a lock.
fn replay(root: &Path, step: &Value, context: &str, holder: &mut Option<Connection>) {
    let text = |name: &str| step[name].as_str().expect(name);
    match text("op") {
        "sql" => {
            let connection = Connection::open(root.join(".sermofur").join("memory.db"))
                .expect("database opened");
            connection
                .execute_batch(&format!("PRAGMA foreign_keys=OFF;{}", text("sql")))
                .expect("SQL");
        }
        "write" => fs::write(root.join(text("path")), text("text")).expect("write"),
        "remove" => fs::remove_file(root.join(text("path"))).expect("remove"),
        "lock" => {
            let connection = Connection::open(root.join(".sermofur").join("memory.db"))
                .expect("database opened");
            connection.execute_batch(text("sql")).expect("lock");
            *holder = Some(connection);
        }
        "unlock" => *holder = None,
        "migrate" => {
            let at = step["crash"].as_str();
            let start = Instant::now();
            let got = answer(migrate_with(root, &mut |name| match at {
                Some(at) if at == name => Err(crash()),
                _ => Ok(()),
            }));
            assert_eq!(got, step["answer"], "{context}: migrate (crash at {at:?})");
            if let Some(elapsed) = step["elapsed"].as_str() {
                assert_eq!(bucket(start), elapsed, "{context}: migrate, elapsed");
            }
        }
        "backup" => {
            // The backup step alone, on a connection opened as `InstanceMigration.Open`.
            let start = Instant::now();
            let got = schema::open(
                &root.join(".sermofur").join("memory.db"),
                OpenFlags::SQLITE_OPEN_READ_WRITE,
            )
            .and_then(|connection| {
                connection
                    .pragma_update(None, "foreign_keys", false)
                    .expect("foreign keys off");
                back_up(&connection, root)
            });
            let got = match got {
                Ok(_) => json!("done"),
                Err(error) => refusal(&error),
            };
            assert_eq!(got, step["answer"], "{context}: backup");
            assert_eq!(bucket(start), step["elapsed"], "{context}: backup, elapsed");
        }
        "race" => {
            // A second migration runs to completion between the backup and the lock.
            let mut winner = None;
            let loser = answer(migrate_with(root, &mut |name| {
                if name == "backup" && winner.is_none() {
                    winner = Some(answer(migrate(root)));
                }
                Ok(())
            }));
            assert_eq!(winner.as_ref(), Some(&step["winner"]), "{context}: winner");
            assert_eq!(loser, step["loser"], "{context}: loser");
        }
        "dump" => check_dump(root, step, context),
        other => panic!("unknown step {other}"),
    }
}

#[test]
fn migrate_answers_and_leaves_the_instance_like_the_dotnet_oracle() {
    let golden: Value = serde_json::from_str(
        &fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/migration.json"),
        )
        .expect("golden file"),
    )
    .expect("JSON");
    let mut count = 0;
    for scenario in golden["scenarios"].as_array().expect("scenarios") {
        let name = scenario["name"].as_str().expect("name");
        let instance = legacy_instance();
        let mut holder = None;
        for (index, step) in scenario["steps"]
            .as_array()
            .expect("steps")
            .iter()
            .enumerate()
        {
            replay(
                &instance.0,
                step,
                &format!("{name}, step {index}"),
                &mut holder,
            );
            count += 1;
        }
    }
    eprintln!("migration.json: {count} steps replayed");
}

#[test]
fn the_backup_name_is_normalized_only_when_it_has_the_shape_of_the_oracle() {
    assert_eq!(
        normalize("a/memory-v1-20261109T101112Z-0123456789abcdef0123456789abcdef.db\""),
        "a/memory-v1-<stamp>-<id>.db\""
    );
    assert_eq!(
        normalize("memory-v1-2026110T101112Z-0123456789abcdef0123456789abcdef.db"),
        "memory-v1-2026110T101112Z-0123456789abcdef0123456789abcdef.db"
    );
}
